package cppgen_test

import (
	"bytes"
	"flag"
	"os"
	"path/filepath"
	"slices"
	"testing"

	cppgen "github.com/fantasim/canonlang/internal/gen/cpp"
	"github.com/fantasim/canonlang/internal/ir"
)

var update = flag.Bool("update", false, "rewrite the goldens under testdata/golden instead of comparing")

// fixture is an IR whose generated files are pinned under testdata/golden/<name>/.
type fixture struct {
	name  string
	build func() *ir.Package
}

var fixtures = []fixture{
	{"pipeline", pipeline}, {"constructs", constructs}, {"imports-base", importBase}, {"imports-app", importApp},
	{"dependent", dependentPackage}, {"inputs", inputsPackage}, {"types-time", typesTimeFixture}, {"types-events", typesEventsFixture},
	{"tablefields", tablesPackage}, {"types-tablefields", tableTypesPackage},
	{"baked", bakedPackage}, {"baked-dependent", bakedDependentPackage},
}

// generate runs the generator twice: the same bytes both times (CODEGEN.md §2.7, NFR-05).
func generate(t *testing.T, p *ir.Package) []ir.File {
	t.Helper()
	first, err := cppgen.Generate(p, cppEmit(p))
	if err != nil {
		t.Fatal(err)
	}
	again, err := cppgen.Generate(p, cppEmit(p))
	if err != nil {
		t.Fatal(err)
	}
	if len(first) != len(again) {
		t.Fatalf("%d files, then %d", len(first), len(again))
	}
	for i, f := range first {
		if f.Path != again[i].Path || !bytes.Equal(f.Content, again[i].Content) {
			t.Errorf("%s differs between two runs", f.Path)
		}
	}
	return first
}

// CODEGEN.md §2.3, §10: every generated file equals its golden byte for byte; -update rewrites them.
func TestGoldens(t *testing.T) {
	for _, fx := range fixtures {
		t.Run(fx.name, func(t *testing.T) {
			files := generate(t, fx.build())
			dir := filepath.Join("testdata", "golden", fx.name)
			if *update {
				rewrite(t, dir, files)
				return
			}
			var names []string
			for _, f := range files {
				names = append(names, f.Path)
				want, err := os.ReadFile(filepath.Join(dir, f.Path))
				if err != nil {
					t.Fatalf("%v (run with -update)", err)
				}
				if !bytes.Equal(f.Content, want) {
					t.Errorf("%s differs from its golden (run with -update and read the diff)", f.Path)
				}
			}
			entries, err := os.ReadDir(dir)
			if err != nil {
				t.Fatal(err)
			}
			for _, e := range entries {
				if !slices.Contains(names, e.Name()) {
					t.Errorf("golden %s is no longer generated", e.Name())
				}
			}
		})
	}
}

func rewrite(t *testing.T, dir string, files []ir.File) {
	t.Helper()
	if err := os.RemoveAll(dir); err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	for _, f := range files {
		if err := os.WriteFile(filepath.Join(dir, f.Path), f.Content, 0o644); err != nil {
			t.Fatal(err)
		}
	}
}

// CODEGEN.md §2.3, §2.4: the files of a data emit, each ending with one line break.
func TestPipelineFiles(t *testing.T) {
	files := generate(t, pipeline())
	var names []string
	for _, f := range files {
		names = append(names, f.Path)
		if !bytes.HasSuffix(f.Content, []byte("\n")) || bytes.HasSuffix(f.Content, []byte("\n\n")) {
			t.Errorf("%s does not end with exactly one line break", f.Path)
		}
	}
	want := []string{"canon_runtime.h", "canon_runtime_json.h", "pipeline.gen.h", "pipeline.gen.cpp", "pipeline_conformance.gen.cpp"}
	if !slices.Equal(names, want) {
		t.Errorf("files %v, want %v", names, want)
	}
	marker := []byte("// GENERATED by canon from pipeline/. DO NOT EDIT.\n")
	for _, f := range files[2:] {
		if !bytes.HasPrefix(f.Content, marker) {
			t.Errorf("%s does not start with the marker", f.Path)
		}
	}
}
